/* Parse public page data as JSON/text only. Never execute Instagram's scripts. */
const InstagramImportModel=(()=>{
 const excluded=new Set(['p','reel','reels','stories','accounts','explore','direct','about','developer','developers','api','legal','challenge','emails','web','embed']);
 function username(input){let value=String(input||'').trim();if(value.length>2048)throw Error('El enlace es demasiado largo.');if(/^@?[\w.]{1,30}$/.test(value))value=value.replace(/^@/,'');else{let url;try{url=new URL(value)}catch{throw Error('Pegá el enlace de un perfil de Instagram.')}if(url.protocol!=='https:'||!['instagram.com','www.instagram.com'].includes(url.hostname)||url.port||url.username||url.password||!/^\/[\w.]{1,30}\/?$/.test(url.pathname))throw Error('Usá un enlace de perfil como https://www.instagram.com/usuario/.');value=url.pathname.split('/')[1]}if(!/^[\w.]{1,30}$/.test(value)||excluded.has(value.toLowerCase()))throw Error('Usá el enlace del perfil, no el de una publicación o historia.');return value.toLowerCase()}
 function imageURL(value){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password&&!u.port&&/^(?:[a-z0-9-]+\.)+(?:cdninstagram\.com|fbcdn\.net)$/.test(u.hostname)&&u.pathname.startsWith('/v/')&&u.href.length<=12000?u.href:null}catch{return null}}
 const decode=s=>String(s||'').replace(/&(#x[\da-f]+|#\d+|amp|quot|apos|lt|gt|nbsp);/gi,(_,v)=>{if(v[0]==='#'){const n=v[1].toLowerCase()==='x'?parseInt(v.slice(2),16):parseInt(v.slice(1),10);return n>0&&n<=0x10ffff?String.fromCodePoint(n):''}return {amp:'&',quot:'"',apos:"'",lt:'<',gt:'>',nbsp:' '}[v.toLowerCase()]});
 function metadata(html){const values={};for(const m of html.matchAll(/<meta\b[^>]*>/gi)){const attrs={};for(const a of m[0].matchAll(/([\w:-]+)\s*=\s*(?:"([^"]*)"|'([^']*)')/g))attrs[a[1].toLowerCase()]=decode(a[2]??a[3]);const name=attrs.property||attrs.name;if(name&&attrs.content)values[name]=attrs.content}return values}
 function jsonObject(source,start){let depth=0,string=false,escape=false;for(let i=start;i<source.length&&i-start<4*1024*1024;i++){const c=source[i];if(string){if(escape)escape=false;else if(c==='\\')escape=true;else if(c==='"')string=false}else if(c==='"')string=true;else if(c==='{')depth++;else if(c==='}'&&!--depth){try{return JSON.parse(source.slice(start,i+1))}catch{return null}}}return null}
 function contexts(html,handle){const found=[];let count=0;const visit=(v,depth=0)=>{if(++count>30000||depth>40)return;if(typeof v==='string'&&v.length<4*1024*1024&&/^[\[{]/.test(v.trim())){try{visit(JSON.parse(v),depth+1)}catch{}}else if(v&&typeof v==='object'){if(typeof v.username==='string'&&v.username.toLowerCase()===handle)found.push(v);for(const x of Object.values(v))visit(x,depth+1)}};for(const script of html.matchAll(/<script\b([^>]*)>([\s\S]*?)<\/script>/gi)){if(/type=["']application\/(?:ld\+)?json["']/.test(script[1])){try{visit(JSON.parse(script[2]))}catch{}}else for(const match of script[2].matchAll(/\b(?:\w+\.)?handle\(\s*\{/g)){visit(jsonObject(script[2],script[2].indexOf('{',match.index)))}}return found}
 const text=(v,max=2200)=>typeof v==='string'?v.slice(0,max):'';
 const number=v=>typeof v==='number'&&Number.isSafeInteger(v)&&v>=0?String(v):typeof v==='string'&&/^\d[\d.,\s]*(?:[KM]|mil|millones)?$/i.test(v.trim())?v.trim():'—';
 function parse(handle,html='',embed=''){
  const meta=metadata(html),users=contexts(embed,handle);if(!users.length)users.push(...contexts(html,handle));
  const user=users.find(u=>Array.isArray(u.graphql_media)||u.edge_owner_to_timeline_media?.edges)||users.find(u=>u.full_name)||users[0]||{};
  const owner=users.find(u=>u.edge_followed_by)||{},counts=(meta['og:description']||meta.description||'').match(/([\d.,\s]+(?:[KMB]|mil|millones)?)\s+Followers,\s*([\d.,\s]+(?:[KMB]|mil|millones)?)\s+Following,\s*([\d.,\s]+(?:[KMB]|mil|millones)?)\s+Posts/i);
  const rawName=(meta['og:title']||'').split(' (@')[0],description=meta.description||'',bioIndex=description.indexOf(' on Instagram:');
  const biography=text(user.biography||(bioIndex>=0?description.slice(bioIndex+14).trim().replace(/^["“]|["”]$/g,''):''));
  const avatar=imageURL(user.profile_pic_url||meta['og:image']);
  if(!users.length&&!(meta['og:title']||'').toLowerCase().includes('(@'+handle+')'))throw Error('Instagram no entregó un perfil público. Puede ser privado, no existir o requerir iniciar sesión.');
  if(meta['og:url']){try{if(username(meta['og:url'])!==handle)throw Error('El perfil recibido no coincide con el enlace.')}catch{throw Error('El perfil recibido no coincide con el enlace.')}}
  const records=user.graphql_media?.map(v=>v.shortcode_media||v)||user.edge_owner_to_timeline_media?.edges?.map(e=>e.node)||[];
  const posts=[],seen=new Set();let photos=0,truncated=false;
  for(const node of records){if(!node||!node.shortcode||seen.has(node.shortcode))continue;seen.add(node.shortcode);if(posts.length>=27||photos>=200){truncated=true;break}const sequence=node.edge_sidecar_to_children?.edges?.map(e=>e.node)||[node],media=[];for(const item of sequence){const url=imageURL(item.display_url);if(!url||media.some(m=>m.url===url))continue;if(media.length>=100||photos+media.length>=200){truncated=true;break}media.push({url,width:item.dimensions?.width||0,height:item.dimensions?.height||0,video:!!item.is_video})}if(!media.length)continue;photos+=media.length;posts.push({id:text(node.shortcode,100),media,caption:text(node.edge_media_to_caption?.edges?.[0]?.node?.text),likes:number(node.edge_liked_by?.count),comments:number(node.edge_media_to_comment?.count),views:number(node.video_view_count),timestamp:Number.isFinite(node.taken_at_timestamp)?node.taken_at_timestamp:null,location:text(node.location?.name,200),pinned:Array.isArray(node.pinned_for_users)&&node.pinned_for_users.some(id=>String(id)===String(user.owner_id)),video:!!node.is_video})}
  const profile={handle,name:text(user.full_name||rawName||handle,200),bio:biography,avatar,followers:number(user.followers_count??user.edge_followed_by?.count??owner.edge_followed_by?.count??counts?.[1]),following:number(user.edge_follow?.count??owner.edge_follow?.count??counts?.[2]),posts:number(user.posts_count??user.edge_owner_to_timeline_media?.count??owner.edge_owner_to_timeline_media?.count??counts?.[3]),verified:!!(user.is_verified||user.verified),private:!!(user.is_private||owner.is_private),link:text(user.external_url,2000)};
  const warnings=['No se importan historias destacadas, mensajes ni estadísticas privadas.'];if(posts.some(p=>p.video||p.media.some(m=>m.video)))warnings.push('Los videos se cargan como imagen de portada, sin reproducción.');if(!posts.length)warnings.push('Instagram no entregó publicaciones: sólo se podrán cargar los datos públicos del perfil.');else if(truncated||/^\d+$/.test(profile.posts)&&Number(profile.posts)>posts.length)warnings.push(`Instagram entregó ${posts.length} publicaciones para esta importación; el perfil puede tener más.`);if(['followers','following','posts'].some(k=>profile[k]==='—'))warnings.push('Las cifras no disponibles se muestran con un guion.');return {profile,posts,photos,warnings,url:'https://www.instagram.com/'+handle+'/'};
 }
 return {username,imageURL,metadata,parse};
})();
if(typeof module!=='undefined')module.exports=InstagramImportModel;
